r observable sink type when null/invalid dereference and out-of-bounds both apply; list at most one CWE unless clearly distinct sink types in different branches; never infer CWE from context alone — require observable sink operation. For control-flow: verify validation precedes dangerous operation; verify guard applies to same pointer/field at sink (when pointer assigned from structured field authkey->payload.data[0] or ptr = obj->field verify whether array/field validated before indexing — if not, assignment is unvalidated even if parent pointer checked); state mismatch explicitly when guard checks one variable but sink uses another derived pointer/field. For localization: evidence snippet must contain sink line(s); include exact dereference lines; quote both source and sink with narrow ranges; higher confidence only when snippet at both source and sink plus correct guard-check, lower when inference/full-range/ambiguous guard. Analysis priorities in sequence: (1) follow actual data-flow from untrusted input sources through each transformation to sink — quote at each step and state attacker-controlled; (2) check integer arithmetic for indexing (off-by-one > vs >=, overflow/underflow/unsigned wrap) against array bounds — quote arithmetic and access; (3) check missing/misplaced null/validity checks BEFORE dereference of pointers derived from untrusted input, verify guard applies to same pointer/field at sink — quote assignment and sink separately; (4) check authorization/authentication order (guard precedes sink and applies to sink object — not different pointer/field); (5) check format-string, command-injection, HTML-output injection where untrusted data reaches sink directly; (6) check missing/null payload/array/data validation before indexing — treat derived pointer indexed without prior validation as unvalidated access. Key failure-pattern checks within each step: derived pointer from structured field (authkey->payload.data[0], ptr=obj->field) — verify array/field validated before indexing, else assignment unvalidated even if parent checked; guard only on parent object but sink on derived pointer — state mismatch explicitly (derived pointer unguarded); dimensions/size validated before loop/decode — confirm guard applies to all paths to sink inside loop. Verification rules: base only on given code; follow actual control-flow paths/checks/state changes; confirm guard applies to attacker-controlled path and to same sink object; do NOT claim vulnerability from snippet showing only validation without visible sink — require both source and sink visible and unguarded or guard misplaced/applying to wrong object; when ambiguous (full-function, missing snippet, guard different variable than sink) prefer conservative verdict with lower confidence and state ambiguity in notes; set confidence proportional to evidence specificity (narrow range + snippet at both source and sink + correct guard-check = high; inference/full-range = low; guard-check mismatch supports vulnerability moderate-high because sink unguarded). Evidence anchoring mandatory: quote snippet at dangerous operation (≤3 lines) and input-to-sink separately; include assignment for derived pointers; include index derivation + access for loops; state whether guard applies to attacker-controlled path; state mismatch explicitly in reasoning. Systematic patterns to correct: high recall (~0.95) with low precision (~0.52) indicates over-labeling — enforce both source and sink visible with specific line ranges before claiming vulnerability; localization precision ~28-31% and CWE accuracy ~20-31% indicate weak anchoring — require snippet at sink with exact dereference for every evidence item and select CWE from observable sink only; unstable pairwise accuracy (6→11→16→13) — emphasize conservative verdict when evidence is ambiguous or guard-check mismatched. Before concluding: confirm snippet contains sink lines, confirm input-to-sink quoted separately, confirm guard applies to sink's object, confirm CWE selected from observable sink operation, confirm confidence set to specificity of evidence. Format: first SCoT reasoning in plain text with numbered Sequence/Branch/Loop steps using quoted snippets with start_line/end_line (≤3 lines) anchoring to code locations; then ONLY one JSON object with no markdown/extra text. JSON: {"verdict":{"vulnerable":true/false,"confidence":0.0-1.0,"cwe":["CWE-..."],"severity":"low|medium|high|critical|unknown","summary":"..."},"evidence":[{"file":null,"function":null,"location":{"start_line":null,"end_line":null},"snippet":"...","reason":"..."}],"notes":{"assumptions":[],"limitations":[]}} Code: static pj_bool_t on_handshake_complete(pj_ssl_sock_t *ssock, 
				       pj_status_t status)
{
    /* Cancel handshake timer */
    if (ssock->timer.id == TIMER_HANDSHAKE_TIMEOUT) {
	pj_timer_heap_cancel(ssock->param.timer_heap, &ssock->timer);
	ssock->timer.id = TIMER_NONE;
    }

    /* Update certificates info on successful handshake */
    if (status == PJ_SUCCESS)
	ssl_update_certs_info(ssock);

    /* Accepting */
    if (ssock->is_server) {
	pj_bool_t ret = PJ_TRUE;

	if (status != PJ_SUCCESS) {
	    /* Handshake failed in accepting, destroy our self silently. */

	    char buf[PJ_INET6_ADDRSTRLEN+10];

	    PJ_PERROR(3,(ssock->pool->obj_name, status,
			 "Handshake failed in accepting %s",
			 pj_sockaddr_print(&ssock->rem_addr, buf,
					   sizeof(buf), 3)));

	    if (ssock->param.cb.on_accept_complete2) {
		(*ssock->param.cb.on_accept_complete2) 
		      (ssock->parent, ssock, (pj_sockaddr_t*)&ssock->rem_addr, 
		      pj_sockaddr_get_len((pj_sockaddr_t*)&ssock->rem_addr), 
		      status);
	    }

	    /* Decrement ref count of parent */
	    if (ssock->parent->param.grp_lock) {
		pj_grp_lock_dec_ref(ssock->parent->param.grp_lock);
		ssock->parent = NULL;
	    }

	    /* Originally, this is a workaround for ticket #985. However,
	     * a race condition may occur in multiple worker threads
	     * environment when we are destroying SSL objects while other
	     * threads are still accessing them.
	     * Please see ticket #1930 for more info.
	     */
#if 1 //(defined(PJ_WIN32) && PJ_WIN32!=0)||(defined(PJ_WIN64) && PJ_WIN64!=0)
	    if (ssock->param.timer_heap) {
		pj_time_val interval = {0, PJ_SSL_SOCK_DELAYED_CLOSE_TIMEOUT};
		pj_status_t status1;

		ssock->ssl_state = SSL_STATE_NULL;
		ssl_close_sockets(ssock);

		if (ssock->timer.id != TIMER_NONE) {
		    pj_timer_heap_cancel(ssock->param.timer_heap,
					 &ssock->timer);
		}
		pj_time_val_normalize(&interval);
		status1 = pj_timer_heap_schedule_w_grp_lock(
						 ssock->param.timer_heap, 
						 &ssock->timer,
						 &interval,
						 TIMER_CLOSE,
						 ssock->param.grp_lock);
		if (status1 != PJ_SUCCESS) {
	    	    PJ_PERROR(3,(ssock->pool->obj_name, status,
				 "Failed to schedule a delayed close. "
				 "Race condition may occur."));
		    ssock->timer.id = TIMER_NONE;
		    pj_ssl_sock_close(ssock);
		}
	    } else {
		pj_ssl_sock_close(ssock);
	    }
#else
	    {
		pj_ssl_sock_close(ssock);
	    }
#endif

	    return PJ_FALSE;
	}

	/* Notify application the newly accepted SSL socket */
	if (ssock->param.cb.on_accept_complete2) {
	    ret = (*ssock->param.cb.on_accept_complete2) 
		    (ssock->parent, ssock, (pj_sockaddr_t*)&ssock->rem_addr, 
		    pj_sockaddr_get_len((pj_sockaddr_t*)&ssock->rem_addr), 
		    status);
	} else if (ssock->param.cb.on_accept_complete) {
	    ret = (*ssock->param.cb.on_accept_complete)
		      (ssock->parent, ssock, (pj_sockaddr_t*)&ssock->rem_addr,
		       pj_sockaddr_get_len((pj_sockaddr_t*)&ssock->rem_addr));
	}

	/* Decrement ref count of parent and reset parent (we don't need it
	 * anymore, right?).
	 */
	if (ssock->parent->param.grp_lock) {
	    pj_grp_lock_dec_ref(ssock->parent->param.grp_lock);
	    ssock->parent = NULL;
	}

	if (ret == PJ_FALSE)
	    return PJ_FALSE;
    }

    /* Connecting */
    else {
	/* On failure, reset SSL socket state first, as app may try to 
	 * reconnect in the callback.
	 */
	if (status != PJ_SUCCESS) {
	    /* Server disconnected us, possibly due to SSL nego failure */
	    ssl_reset_sock_state(ssock);
	}
	if (ssock->param.cb.on_connect_complete) {
	    pj_bool_t ret;
	    ret = (*ssock->param.cb.on_connect_complete)(ssock, status);
	    if (ret == PJ_FALSE)
		return PJ_FALSE;
	}
    }

    return PJ_TRUE;
}

